#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import shutil, sqlite3, ast, py_compile, base64

P=Path(__file__).resolve().parent
DB=P/'loan_bot.db'
CORE=['bot.py','database.py','admin_panel.py','loan_callbacks.py','i18n.py','notifications.py','kyc_flow.py','api.py']
MODULE_B64='''
'''

def fail(msg):
    print('❌ '+msg); raise SystemExit(1)

def backup():
    d=P/'backups'/('enterprise_upgrade_'+datetime.now().strftime('%Y%m%d_%H%M%S'))
    d.mkdir(parents=True,exist_ok=True)
    for n in CORE+['loan_bot.db']:
        f=P/n
        if f.exists(): shutil.copy2(f,d/f.name)
    print('💾 Backup créé :',d)

def migrate():
    if not DB.exists(): fail('loan_bot.db introuvable')
    c=sqlite3.connect(DB,timeout=30); c.execute('PRAGMA busy_timeout=30000')
    try:
        c.execute('BEGIN')
        c.executescript('''
CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS repayment_records(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER NOT NULL,telegram_id INTEGER NOT NULL,amount REAL NOT NULL,txid TEXT NOT NULL,recorded_by INTEGER NOT NULL,status TEXT DEFAULT 'confirmed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,telegram_id INTEGER NOT NULL,subject TEXT,message TEXT NOT NULL,status TEXT DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMP);
''')
        spec={'users':{'updated_at':'TIMESTAMP','last_seen_at':'TIMESTAMP'},'loan_requests':{'updated_at':'TIMESTAMP','rejection_reason':'TEXT'},'loans':{'approved_at':'TIMESTAMP','completed_at':'TIMESTAMP','last_payment_at':'TIMESTAMP'},'loan_installments':{'amount_paid':'REAL DEFAULT 0'}}
        for table, wanted in spec.items():
            have={r[1] for r in c.execute(f'PRAGMA table_info({table})')}
            for name,definition in wanted.items():
                if name not in have:
                    c.execute(f'ALTER TABLE {table} ADD COLUMN {name} {definition}')
                    print('  +',table+'.'+name)
        for key,val in [('interest_rate_monthly','1.0'),('guarantee_rate','0.15'),('min_duration_months','6'),('max_duration_months','44')]:
            c.execute('INSERT OR IGNORE INTO system_settings(key,value) VALUES(?,?)',(key,val))
        c.execute('UPDATE loan_installments SET amount_paid=COALESCE(amount_paid,0)')
        c.commit()
    except:
        c.rollback(); raise
    finally: c.close()
    print('🗄️ Migration SQLite OK')

def install_module():
    (P/'enterprise_features.py').write_bytes(base64.b64decode(MODULE_B64.strip()))
    print('🧩 Module enterprise installé')

def patch_database():
    p=P/'database.py'; s=p.read_text(encoding='utf-8'); old=s
    s=s.replace('interest_rate REAL NOT NULL DEFAULT 5,','interest_rate REAL NOT NULL DEFAULT 1.0,')
    if 'def ensure_enterprise_schema()' not in s:
        marker='\n\nif __name__ == "__main__":'
        fn='''\n\ndef ensure_enterprise_schema():\n    conn = get_connection()\n    try:\n        conn.execute("PRAGMA busy_timeout=30000")\n        conn.executescript("CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS repayment_records(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER NOT NULL,telegram_id INTEGER NOT NULL,amount REAL NOT NULL,txid TEXT NOT NULL,recorded_by INTEGER NOT NULL,status TEXT DEFAULT 'confirmed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,telegram_id INTEGER NOT NULL,subject TEXT,message TEXT NOT NULL,status TEXT DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMP);")\n        conn.commit()\n    finally:\n        conn.close()\n'''
        s=s.replace(marker,fn+marker)
    if s!=old:
        p.write_text(s,encoding='utf-8'); print('🔧 database.py mis à jour')

def patch_bot():
    p=P/'bot.py'; s=p.read_text(encoding='utf-8'); old=s
    if 'from enterprise_features import register_enterprise_handlers, ensure_enterprise_schema' not in s:
        s=s.replace('from database import init_database','from database import init_database\nfrom enterprise_features import register_enterprise_handlers, ensure_enterprise_schema',1)
    s=s.replace('duration=months,\n                    interest=interest,','duration=duration,\n                    interest=interest,')
    if 'ensure_enterprise_schema()' not in s:
        s=s.replace('def main():\n\n    init_database()','def main():\n\n    init_database()\n    ensure_enterprise_schema()',1)
    if 'register_enterprise_handlers(application)' not in s:
        needle='application = Application.builder().token(TOKEN).connect_timeout(30).read_timeout(30).write_timeout(30).pool_timeout(30).build()'
        if needle not in s: fail('ligne Application introuvable')
        s=s.replace(needle,needle+'\n\n    register_enterprise_handlers(application)',1)
    if s!=old:
        p.write_text(s,encoding='utf-8'); print('🤖 bot.py mis à jour')

def tests():
    for n in CORE+['enterprise_features.py']:
        f=P/n
        if f.exists():
            ast.parse(f.read_text(encoding='utf-8'),filename=str(f))
            py_compile.compile(str(f),doraise=True)
    c=sqlite3.connect(DB); integrity=c.execute('PRAGMA integrity_check').fetchone()[0]; tables={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}; c.close()
    if integrity!='ok': fail('SQLite integrity_check: '+integrity)
    for t in ('system_settings','repayment_records','support_tickets'):
        if t not in tables: fail('table absente: '+t)
    print('🧪 Syntaxe + SQLite : OK')

def main():
    print('🚀 UPGRADE AUTOMATIQUE — Loan Request Assistant')
    if not (P/'bot.py').exists(): fail('bot.py introuvable')
    backup(); migrate(); install_module(); patch_database(); patch_bot(); tests()
    print('\n🎉 UPGRADE TERMINÉ')
    print('✅ Backup')
    print('✅ Base migrée sans suppression des données')
    print('✅ Remboursements administratifs tracés')
    print('✅ Tickets support')
    print('✅ /enterprise /loanstatus /schedule /support /tickets /ticket_close /repay')
    print('✅ FR / EN / ES / PT pour les nouvelles fonctions client')
    print('✅ Blocage des messages de groupe')
    print('✅ Correction du bug duration/months')
    print('\n➡️ Ensuite : python bot.py')
    print('⚠️ Aucun transfert crypto automatique n’est ajouté.')

if __name__=='__main__': main()
